const raw = $input.first().json;
if (raw.status !== 'completed') throw new Error('OpenAI não concluiu: ' + (raw.incomplete_details?.reason ?? raw.error?.message ?? raw.status ?? 'resposta inválida'));
const content = (raw.output ?? []).flatMap(o => o.content ?? []);
if (content.some(c => c.type === 'refusal')) throw new Error('OpenAI recusou esta extração.');
const text = content.filter(c => c.type === 'output_text').map(c => c.text).join('');
if (!text) throw new Error('OpenAI não retornou JSON.');
const p = JSON.parse(text);
for (const k of ['categorias', 'regras', 'regrasGerais', 'conflitos', 'pendencias']) if (!Array.isArray(p[k])) throw new Error('Contrato inválido: ' + k);
const normalize = x => String(x ?? '').replace(/\s+/g, ' ').trim();
const issues = [], ids = new Set(), cats = new Set();
for (const c of p.categorias) { if (cats.has(c.id)) throw new Error('Categoria duplicada: ' + c.id); cats.add(c.id); }
for (const r of [...p.regras, ...p.regrasGerais]) { if (ids.has(r.id)) throw new Error('Regra duplicada: ' + r.id); ids.add(r.id); }
function evidence(e, owner) { if (!normalize(e.trecho)) { issues.push({ id: owner, tipo: 'evidencia_sem_trecho', detalhe: 'Evidência sem trecho literal.' }); return false; } return true; }
for (const c of p.categorias) { if (!(c.evidencias ?? []).length) issues.push({ id: c.id, tipo: 'categoria_sem_evidencia' }); for (const e of c.evidencias ?? []) evidence(e, c.id); }

// Regras gerais que repetem literalmente uma regra já extraída são consolidadas.
// A relação explícita entre IDs evita juntar normas apenas parecidas.
const duplicateOf = new Map();
const signature = r => (r.evidencias ?? []).map(e => `${e.pagina ?? ''}:${normalize(e.trecho).toLowerCase()}`).sort().join('|');
for (const general of p.regrasGerais) {
  const specific = p.regras.find(r => (general.regrasRelacionadas ?? []).includes(r.id)
    && general.efeito === r.efeito && signature(general) && signature(general) === signature(r));
  if (specific) duplicateOf.set(general.id, specific.id);
}
const canonical = id => duplicateOf.get(id) ?? id;
const distinct = values => [...new Set((values ?? []).map(canonical))];
p.regrasGerais = p.regrasGerais.filter(r => !duplicateOf.has(r.id));
const all = [...p.regras, ...p.regrasGerais];
const activeIds = new Set(all.map(r => r.id));
for (const r of all) {
  r.regrasGeraisAplicaveis = distinct(r.regrasGeraisAplicaveis).filter(id => id !== r.id);
  r.regrasRelacionadas = distinct(r.regrasRelacionadas).filter(id => id !== r.id);
  for (const ex of r.excecoes ?? []) ex.regrasModificadas = distinct(ex.regrasModificadas);
  const start = issues.length;
  if (r.categoria !== null && !cats.has(r.categoria)) issues.push({ id: r.id, tipo: 'categoria_inexistente' });
  if (!(r.evidencias ?? []).length) issues.push({ id: r.id, tipo: 'regra_sem_evidencia' });
  for (const e of r.evidencias ?? []) evidence(e, r.id);
  for (const id of [...r.regrasGeraisAplicaveis, ...r.regrasRelacionadas, ...(r.excecoes ?? []).flatMap(e => e.regrasModificadas ?? [])]) if (!activeIds.has(id)) issues.push({ id: r.id, tipo: 'referencia_inexistente', referencia: id });
  if (r.condicoes?.predicados?.length) { issues.push({ id: r.id, tipo: 'predicado_sem_contrato' }); r.condicoes.predicados = []; }
  if (issues.length > start) { r.prontidao = 'revisao_manual'; r.pendencias = [...(r.pendencias ?? []), 'Validação estrutural encontrou inconsistências; consultar validacao.alertas.']; }
}
for (const c of p.conflitos) {
  c.regrasEnvolvidas = distinct(c.regrasEnvolvidas);
  for (const e of c.evidencias ?? []) evidence(e, 'conflito');
  for (const id of c.regrasEnvolvidas) {
    const r = all.find(x => x.id === id);
    if (r) { r.prontidao = 'revisao_manual'; r.pendencias = [...(r.pendencias ?? []), c.motivo]; }
    else issues.push({ id, tipo: 'conflito_referencia_inexistente' });
  }
}
for (const x of p.pendencias) x.regrasAfetadas = distinct(x.regrasAfetadas);

// Uma dependência externa ou uma dúvida de redação não é contradição confirmada.
function issueType(c) {
  const m = normalize(c.motivo).toLowerCase();
  if (/não há conflito material|não existe conflito material/.test(m)) return 'ambiguidade';
  if (/não foi fornecid|tabela externa|convenção coletiva|calendário não fornecido/.test(m)) return 'dependencia_externa';
  if (/não está explicitad|poderia|não define|exige interpretação|relação entre|não é claro/.test(m)) return 'ambiguidade';
  return 'conflito_potencial';
}
const questoesInterpretacao = p.conflitos.map(c => ({ ...c, tipoLeitura: issueType(c) }));
const counts = { estruturada: 0, depende_parametro: 0, revisao_manual: 0 };
for (const r of all) counts[r.prontidao] = (counts[r.prontidao] ?? 0) + 1;
const resumoPrimeiraLeitura = {
  vigenciaConfirmada: p.politica?.vigenciaConfirmada === true,
  versaoInformada: !!normalize(p.politica?.versao),
  datas: p.politica?.datas ?? [],
  categorias: p.categorias.length,
  regrasUnicas: all.length,
  regrasPorProntidao: counts,
  duplicatasConsolidadas: [...duplicateOf].map(([removida, mantida]) => ({ removida, mantida })),
  pendenciasDeFonteExterna: p.pendencias.filter(x => /extern|parâmetro|parametro/i.test(x.tipo ?? '')),
  questoesDeInterpretacao: questoesInterpretacao,
  observacao: 'Leitura estruturada para revisão. Nenhuma conclusão foi conferida automaticamente contra o PDF original.'
};
const resultado = { ...p, questoesInterpretacao, resumoPrimeiraLeitura,
  validacao: { status: issues.length ? 'com_alertas' : 'estrutura_conferida', alertas: issues, observacao: 'Validação estrutural do contrato; trechos citados não foram conferidos automaticamente contra o PDF. Pendências de negócio e vigência são mostradas separadamente.' },
  execucao: { modelo: raw.model, responseId: raw.id, uso: raw.usage, promptVersion: 'policy-pdf-v3', pagamentoExecutado: false, aprovacaoExecutada: false } };

const t = ['POLÍTICA DE DESPESAS — PRIMEIRA LEITURA', p.politica?.identificacao ?? 'Identificação não informada', 'Organização: ' + (p.politica?.organizacao ?? 'Não informada'), 'Versão: ' + (p.politica?.versao ?? 'Não informada'), 'Datas citadas: ' + ((p.politica?.datas ?? []).join(', ') || 'Não informadas'), 'Vigência: ' + (resumoPrimeiraLeitura.vigenciaConfirmada ? 'confirmada pelo documento' : 'NÃO CONFIRMADA — verificar versão vigente'), '',
  'RESUMO PARA DECISÃO',
  `Categorias: ${p.categorias.length} | Regras únicas: ${all.length} | Estruturadas: ${counts.estruturada} | Dependem de parâmetro: ${counts.depende_parametro} | Revisão manual: ${counts.revisao_manual}`,
  `Duplicatas consolidadas: ${duplicateOf.size} | Pendências: ${p.pendencias.length} | Questões de interpretação: ${questoesInterpretacao.length}`,
  'A extração organiza a política; não aprova despesas nem autoriza pagamentos.', ''];
if (!resumoPrimeiraLeitura.vigenciaConfirmada || !resumoPrimeiraLeitura.versaoInformada || p.pendencias.length || questoesInterpretacao.length) {
  t.push('PONTOS A CONFIRMAR ANTES DE AUTOMATIZAR');
  if (!resumoPrimeiraLeitura.vigenciaConfirmada) t.push('- Confirmar qual documento está vigente.');
  if (!resumoPrimeiraLeitura.versaoInformada) t.push('- Identificar a versão da política.');
  for (const x of p.pendencias) t.push('- ' + x.informacaoNecessaria + (x.impactoAutomacao ? ' — ' + x.impactoAutomacao : ''));
  t.push('');
}
t.push('CATEGORIAS', ...p.categorias.map(c => '- ' + c.nome + ': ' + c.descricao), '');
function valueLine(r) {
  if (r.valorLimite == null) return null;
  const unit = r.unidadeOriginal && /dia|hora|úte|corrid/i.test(r.unidadeOriginal) ? r.unidadeOriginal : (r.unidadeLimite ?? r.unidadeOriginal ?? 'unidade não informada');
  if (r.moeda) return `Valor: ${r.valorLimite} ${r.moeda} / ${unit}`;
  if (/dia|hora|prazo/i.test(unit + ' ' + (r.motivoLimite ?? ''))) return `Prazo: ${r.valorLimite} ${unit === 'dia' ? 'dia(s)' : unit}`;
  return `Quantidade: ${r.valorLimite} / ${unit}`;
}
for (const r of all) {
  t.push(r.id + ' | ' + r.descricao, 'Categoria: ' + (p.categorias.find(c => c.id === r.categoria)?.nome ?? 'Regra geral / não definida'), 'Efeito: ' + r.efeito + ' | Prontidão: ' + r.prontidao, 'Escopo: ' + r.escopo, 'Condições: ' + (r.condicoes?.redacao ?? 'Não informadas'));
  const value = valueLine(r); if (value) t.push(value);
  if ((r.documentosExigidos ?? []).length) t.push('Documentos: ' + r.documentosExigidos.join('; '));
  for (const a of r.aprovacoesExigidas ?? []) t.push('Aprovação: ' + (a.quem ?? 'não informado') + ' — ' + a.objeto + ' — ' + (a.momento ?? 'momento não informado'));
  for (const e of r.evidencias ?? []) t.push('Fonte' + (e.pagina ? ' p.' + e.pagina : '') + ': ' + e.trecho);
  if ((r.pendencias ?? []).length) t.push('Pendências: ' + [...new Set(r.pendencias)].join('; '));
  t.push('');
}
t.push('QUESTÕES DE INTERPRETAÇÃO');
for (const c of questoesInterpretacao) t.push('[' + c.tipoLeitura + '] ' + c.motivo + ' Pergunta: ' + c.perguntaResolucao);
t.push('', 'PENDÊNCIAS DE DADOS E PARÂMETROS');
for (const x of p.pendencias) t.push('[' + (x.tipo ?? 'não classificada') + '] ' + x.informacaoNecessaria + ' — ' + x.impactoAutomacao);
t.push('', 'VALIDAÇÃO', issues.length + ' alerta(s) estruturais; ' + p.pendencias.length + ' pendência(s) de negócio; ' + questoesInterpretacao.length + ' questão(ões) de interpretação. Evidências não conferidas automaticamente contra o PDF.', '');

// O quadro é sempre a última seção do relatório.
const rows = [...p.categorias.map(c => ({ id: c.id, nome: c.nome })), { id: null, nome: 'Regras gerais' }].map(c => {
  const rules = all.filter(r => r.categoria === c.id);
  return [c.nome, ...['estruturada', 'depende_parametro', 'revisao_manual'].map(s => rules.filter(r => r.prontidao === s).length), rules.length];
});
t.push('QUADRO FINAL — CONTAGEM DE REGRAS ÚNICAS', '| Categoria | Estruturadas | Dependem de parâmetro | Revisão manual | Total |', '|---|---:|---:|---:|---:|');
for (const row of rows) t.push('| ' + row.join(' | ') + ' |');
t.push(`| TOTAL | ${counts.estruturada} | ${counts.depende_parametro} | ${counts.revisao_manual} | ${all.length} |`);
t.push(`Itens recebidos: ${all.length + duplicateOf.size}; duplicatas consolidadas: ${duplicateOf.size}; regras únicas: ${all.length}.`);

const name = ($('Validar PDF e preparar Base64').first().json.fileName ?? 'politica.pdf').replace(/\.pdf$/i, '');
return [{ json: resultado, binary: {
  data: await this.helpers.prepareBinaryData(Buffer.from(JSON.stringify(resultado, null, 2), 'utf8'), name + '-politica.json', 'application/json'),
  relatorio: await this.helpers.prepareBinaryData(Buffer.from(t.join('\n'), 'utf8'), name + '-relatorio.txt', 'text/plain')
} }];
